var t=`1419-poi-with-coconut`;var n=`world-1419`;var a=`SB`;var i=`oceania`;var r=4;var s=54;var l={en:`Poi with Coconut`,ua:`Пої з кокосом`};var c={en:`Solomon Islands-inspired starchy poi with coconut. This version makes a smooth cooked-taro purée; local poi recipes vary by island and root crop.`,ua:`Пої з кокосом за мотивами кухні Соломонових Островів. Ця версія, пюре з вареного таро; місцеві способи приготування пої відрізняються залежно від острова й коренеплоду.`};var m=[{en:`Peel purchased edible taro and boil in plenty of water until fully soft, 30–35 minutes. Drain thoroughly.`,ua:`Очистіть придбане харчове таро й варіть у великій кількості води до повної м’якості 30–35 хвилин. Ретельно злийте воду.`,t:[`boiling`,`draining`],m:35,i:[[`taro-root`,850,`g`],[`water`,1600,`ml`]]},{en:`Mash the hot cooked taro into a smooth, dense paste, adding a spoonful of hot water only if needed.`,ua:`Розімніть гаряче приготовлене таро до гладкої густої пасти, за потреби додайте ложку гарячої води.`,t:[`mashing`],m:10,i:[[`water`,50,`ml`]]},{en:`Warm coconut cream gently with a pinch of salt; stir most into the taro and reserve some to pour on top.`,ua:`Обережно підігрійте кокосові вершки з дрібкою солі; більшу частину вмішайте в таро, решту залиште для поливання.`,t:[`gentle-simmering`],m:6,i:[[`coconut-cream`,280,`ml`],[`sea-salt`,4,`g`]]},{en:`Shape onto a platter, pour over remaining coconut cream and serve warm.`,ua:`Викладіть на блюдо, полийте рештою кокосових вершків і подавайте теплим.`,t:[`garnishing`],m:3,i:[]}];var u={slug:t,id:n,country:`SB`,region:i,servings:4,minutes:54,title:l,text:c,steps:m};export{a as country,u as default,n as id,s as minutes,i as region,r as servings,t as slug,m as steps,c as text,l as title};